ON DUPLICATE KEY UPDATE
  mapped_keys_json = VALUES(mapped_keys_json),
  is_active = VALUES(is_active);

ON DUPLICATE KEY UPDATE `mapped_key`=VALUES(`mapped_key`), `kategori_hint`=VALUES(`kategori_hint`), `sort_order`=VALUES(`sort_order`), `is_active`=VALUES(`is_active`);
ON DUPLICATE KEY UPDATE `mapped_key`=VALUES(`mapped_key`), `kategori_hint`=VALUES(`kategori_hint`), `sort_order`=VALUES(`sort_order`), `is_active`=VALUES(`is_active`);
ON DUPLICATE KEY UPDATE `mapped_key`=VALUES(`mapped_key`), `kategori_hint`=VALUES(`kategori_hint`), `sort_order`=VALUES(`sort_order`), `is_active`=VALUES(`is_active`);


UPDATE `alternatives`
SET is_active = 0
WHERE tujuan_karir IN ('kuliah','kerja','wirausaha');

UPDATE `roadmap_master`
SET is_active = 0
WHERE target_type IN ('kuliah','kerja','wirausaha')
  AND (title LIKE 'Roadmap %' OR recommended_for IS NOT NULL);
UPDATE `roadmap_step` s
JOIN `roadmap_master` rm ON rm.id_roadmap = s.id_roadmap
SET s.is_active = 0
WHERE rm.target_type IN ('kuliah','kerja','wirausaha')
  AND rm.is_active = 0;
UPDATE `roadmap_step_detail` d
JOIN `roadmap_step` s ON s.id_roadmap_step = d.id_roadmap_step
JOIN `roadmap_master` rm ON rm.id_roadmap = s.id_roadmap
SET d.is_active = 0
WHERE rm.target_type IN ('kuliah','kerja','wirausaha')
  AND rm.is_active = 0;


ON DUPLICATE KEY UPDATE `kategori`=VALUES(`kategori`), `profil_tag_json`=VALUES(`profil_tag_json`), `akademik_json`=VALUES(`akademik_json`), `sort_order`=VALUES(`sort_order`), `is_active`=VALUES(`is_active`);
ON DUPLICATE KEY UPDATE `kategori`=VALUES(`kategori`), `profil_tag_json`=VALUES(`profil_tag_json`), `akademik_json`=VALUES(`akademik_json`), `sort_order`=VALUES(`sort_order`), `is_active`=VALUES(`is_active`);


SELECT a.id,
       LEFT(CONCAT('Roadmap ', a.nama), 180),
       CASE a.tujuan_karir
         WHEN 'kuliah' THEN CONCAT('Roadmap kuliah untuk ', a.nama, ': validasi prodi, persiapan seleksi, portofolio, dan rencana belajar awal.')
         WHEN 'kerja' THEN CONCAT('Roadmap kerja untuk ', a.nama, ': pahami peran, bangun skill, siapkan portofolio/CV, dan latihan melamar kerja.')
         WHEN 'wirausaha' THEN CONCAT('Roadmap wirausaha untuk ', a.nama, ': validasi ide, uji pasar, susun operasional, dan mulai legalitas dasar.')
         ELSE CONCAT('Roadmap untuk ', a.nama)
       END,
       a.kategori,
       a.tujuan_karir,
       LEFT(a.nama, 120),
       1
FROM alternatives a
WHERE a.is_active = 1
  AND a.sort_order BETWEEN 11001 AND 31999
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), category=VALUES(category),
  target_type=VALUES(target_type), recommended_for=VALUES(recommended_for), is_active=VALUES(is_active);

DELETE d FROM roadmap_step_detail d
JOIN roadmap_step s ON s.id_roadmap_step = d.id_roadmap_step
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.is_active = 1 AND a.sort_order BETWEEN 11001 AND 31999;

DELETE s FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.is_active = 1 AND a.sort_order BETWEEN 11001 AND 31999;


