SELECT s.id_roadmap_step, 'Cek nama prodi dan bidang ilmu', 'Gunakan PDDikti untuk mencari prodi terkait Sistem Informasi, lalu catat minimal 3 kampus dan akreditasinya.', 'https://pddikti.kemdiktisaintek.go.id/program-studi', 'referensi resmi', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
WHERE rm.target_type='kuliah' AND rm.recommended_for='Sistem Informasi' AND s.step_order=1 AND rm.is_active=1;
SELECT s.id_roadmap_step, 'Cek jalur seleksi yang cocok', 'Bandingkan kebutuhan nilai/portofolio untuk masuk Sistem Informasi, termasuk SNBP/SNBT/mandiri bila relevan.', 'https://snpmb.bppp.kemdikbud.go.id/', 'seleksi kuliah', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
WHERE rm.target_type='kuliah' AND rm.recommended_for='Sistem Informasi' AND s.step_order=1 AND rm.is_active=1;
SELECT s.id_roadmap_step, 'Buat ringkasan kompetensi inti', 'Tulis 5 kompetensi yang sering dipakai di Sistem Informasi, lalu hubungkan dengan nilai akademik dan minat kamu.', NULL, 'aktivitas', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
WHERE rm.target_type='kuliah' AND rm.recommended_for='Sistem Informasi' AND s.step_order=2 AND rm.is_active=1;
SELECT s.id_roadmap_step, 'Kerjakan latihan terarah', 'Buat proyek teknis kecil yang bisa diuji, misalnya aplikasi, konfigurasi jaringan, dashboard, atau otomatisasi sederhana.', NULL, 'praktik', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
WHERE rm.target_type='kuliah' AND rm.recommended_for='Sistem Informasi' AND s.step_order=2 AND rm.is_active=1;
SELECT s.id_roadmap_step, 'Kumpulkan bukti prestasi dan sertifikat', 'Masukkan sertifikat, proyek sekolah, laporan praktikum, karya, atau kegiatan yang relevan dengan Sistem Informasi.', NULL, 'portofolio', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
WHERE rm.target_type='kuliah' AND rm.recommended_for='Sistem Informasi' AND s.step_order=3 AND rm.is_active=1;
SELECT s.id_roadmap_step, 'Minta review guru/BK', 'Minta guru mapel atau BK menilai apakah arah Sistem Informasi sudah cocok dengan kemampuan dan nilai kamu.', NULL, 'evaluasi', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap=s.id_roadmap
